From c0cb5fff75be884deffc989645919f1483d927ed Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 20:42:23 +0100
Subject: [PATCH] wallpapers/potd: allow saving the image without a Save dialog

The lock screen can't open a Save dialog, so the picture couldn't be
kept from there. Add a call that copies it to the Pictures folder under
a free name and expose it on the wallpaper item for the lock screen.

BUG: 484359
---
 wallpapers/potd/package/contents/ui/main.qml |  9 ++++
 wallpapers/potd/plugins/potdbackend.cpp      | 52 +++++++++++++++++---
 wallpapers/potd/plugins/potdbackend.h        |  7 +++
 3 files changed, 62 insertions(+), 6 deletions(-)

diff --git a/wallpapers/potd/package/contents/ui/main.qml b/wallpapers/potd/package/contents/ui/main.qml
index b179ce7e6..724e0732a 100644
--- a/wallpapers/potd/package/contents/ui/main.qml
+++ b/wallpapers/potd/package/contents/ui/main.qml
@@ -18,6 +18,14 @@ import org.kde.plasma.plasmoid
 WallpaperItem {
     id: root

+    // Used by the lock screen to save the image without a Save dialog
+    readonly property bool canSaveImage: backend.localUrl.length > 0
+    signal imageSaveFinished(string message)
+
+    function saveImage(): void {
+        backend.saveImageToPicturesFolder();
+    }
+
     contextualActions: [
         PlasmaCore.Action {
             text: i18nd("plasma_wallpaper_org.kde.potd", "Open Wallpaper Image")
@@ -102,6 +110,7 @@ WallpaperItem {

             onImageChanged: Qt.callLater(imageView.loadImage)
             onLocalUrlChanged: Qt.callLater(imageView.loadImage)
+            onSaveStatusChanged: root.imageSaveFinished(backend.saveStatusMessage)
         }

         Component {
diff --git a/wallpapers/potd/plugins/potdbackend.cpp b/wallpapers/potd/plugins/potdbackend.cpp
index ae54e353a..8ac01f99c 100644
--- a/wallpapers/potd/plugins/potdbackend.cpp
+++ b/wallpapers/potd/plugins/potdbackend.cpp
@@ -7,10 +7,12 @@
 #include "potdbackend.h"

 #include <QDBusConnection>
+#include <QDir>
 #include <QFileDialog>
 #include <QNetworkInformation>
 #include <QStandardPaths> // For "Pictures" folder

+#include <KFileUtils>
 #include <KIO/CopyJob> // For "Save Image"
 #include <KLocalizedString>

@@ -168,12 +170,8 @@ void PotdBackend::setUpdateOverMeteredConnection(int value)
     }
 }

-void PotdBackend::saveImage()
+QString PotdBackend::defaultSavePath() const
 {
-    if (m_client->m_localPath.isEmpty()) {
-        return;
-    }
-
     auto sanitizeFileName = [](const QString &name) {
         if (name.isEmpty()) {
             return name;
@@ -207,11 +205,20 @@ void PotdBackend::saveImage()
         defaultFileName += QDate::currentDate().toString();
     }

+    return path + QLatin1String("/") + sanitizeFileName(defaultFileName) + QLatin1String(".jpg");
+}
+
+void PotdBackend::saveImage()
+{
+    if (m_client->m_localPath.isEmpty()) {
+        return;
+    }
+
     m_savedUrl = QUrl::fromLocalFile( //
         QFileDialog::getSaveFileName( //
             nullptr, //
             i18ndc("plasma_wallpaper_org.kde.potd", "@title:window", "Save Today's Picture"), //
-            path + QLatin1String("/") + sanitizeFileName(defaultFileName) + QLatin1String(".jpg"), //
+            defaultSavePath(), //
             i18ndc("plasma_wallpaper_org.kde.potd", "@label:listbox Template for file dialog", "JPEG image (*.jpeg *.jpg *.jpe)"), //
             nullptr, //
             QFileDialog::DontConfirmOverwrite // KIO::CopyJob will show the confirmation dialog.
@@ -246,6 +253,39 @@ void PotdBackend::saveImage()
     copyJob->start();
 }

+void PotdBackend::saveImageToPicturesFolder()
+{
+    if (!m_client || m_client->m_localPath.isEmpty()) {
+        return;
+    }
+
+    const QFileInfo defaultFile(defaultSavePath());
+    QDir().mkpath(defaultFile.absolutePath());
+
+    m_savedFolder = QUrl::fromLocalFile(defaultFile.absolutePath());
+    m_savedUrl = QUrl::fromLocalFile(defaultFile.absoluteFilePath());
+    if (defaultFile.exists()) {
+        m_savedUrl = QUrl::fromLocalFile(defaultFile.absoluteDir().filePath(KFileUtils::suggestName(m_savedFolder, defaultFile.fileName())));
+    }
+
+    KIO::CopyJob *copyJob = KIO::copyAs(QUrl::fromLocalFile(m_client->m_localPath), m_savedUrl, KIO::HideProgressInfo);
+    connect(copyJob, &KJob::finished, this, [this](KJob *job) {
+        if (job->error()) {
+            m_saveStatusMessage = job->errorText();
+            if (m_saveStatusMessage.isEmpty()) {
+                m_saveStatusMessage = i18ndc("plasma_wallpaper_org.kde.potd", "@info:status after a save action", "The image was not saved.");
+            }
+            m_saveStatus = FileOperationStatus::Failed;
+        } else {
+            m_saveStatusMessage =
+                i18ndc("plasma_wallpaper_org.kde.potd", "@info:status after a save action %1 file path", "The image was saved as %1", m_savedUrl.toLocalFile());
+            m_saveStatus = FileOperationStatus::Successful;
+        }
+        Q_EMIT saveStatusChanged();
+    });
+    copyJob->start();
+}
+
 void PotdBackend::registerClient()
 {
     if (!m_ready) {
