 Q_SIGNALS:
     void identifierChanged();
     void argumentsChanged();
@@ -127,6 +133,7 @@ Q_SIGNALS:

 private:
     void registerClient();
+    QString defaultSavePath() const;

     bool m_ready = false;
     bool m_networkInfomationAvailable = false;
